    row.querySelector('input').addEventListener('change', async (event) => {
      await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: event.target.checked }) });
      loadTasks();
    });
    taskList.append(row);
  }
};
app.querySelector('#task-filter').addEventListener('change', loadTasks);
